insert into public.services (slug,title,description,details,number_label,line,position,is_published,updated_at) values
('identity','Visual Identity','Turning strategic brand intent into a recognisable visual form. A complete visual grammar — logo systems, proprietary type pairings, colour scales and identity manuals built to last.','["Brand Architecture & Strategy","Logo Marks & Symbol Systems","Custom Typographic Scales","Comprehensive Identity Guidelines"]'::jsonb,'01','Strategic brand marks, typography systems & identity architecture.',0,TRUE,'2026-10-29T07:17:46.633Z'),
('art-direction','Art Direction','Defining the visual dimension of campaigns and brand narratives. Photography direction, set styling, cinematic colour grading and commercial rollout systems for national and global markets.','["Campaign Visual Concepts","Photography & Video Treatments","Master Key Visuals (KV)","Multi-Channel Rollout Systems"]'::jsonb,'02','Campaign conception, visual storytelling & photography direction.',1,TRUE,'2026-10-29T07:17:46.633Z'),
('editorial','Editorial & Print','Editorial compositions, annual reports, large-format billboards, product packaging and print production oversight — with typographic rigour from screen to press.','["Editorial Books & Publications","Large-Format OOH & Billboards","Packaging & Structural Design","Print Production & Finish Specs"]'::jsonb,'03','Tactile publications, large-format OOH & packaging design.',2,TRUE,'2026-10-29T07:17:46.633Z'),
('digital','Digital Design','Modular digital ecosystems that keep a brand present and in rhythm. Social publishing systems, UI/UX aesthetics, digital campaign kits, motion graphics and interactive web interfaces.','["Social-First Content Systems","Dynamic Motion Language","Digital Design Systems","Interactive Web Experiences"]'::jsonb,'04','Social-first content engines, motion assets & digital systems.',3,TRUE,'2026-10-29T07:17:46.633Z'),
('ai','AI Creative Direction','Using AI as a production instrument, not a shortcut — concept exploration, image synthesis, retouching and content at scale, always held to the brand system and human judgement.','["AI Concept Exploration","Generative Key Art","Image Manipulation & Retouch","Scaled Content Production"]'::jsonb,'05','Generative pipelines directed with an art director''s eye.',4,TRUE,'2026-10-29T07:17:46.633Z')
