insert into public.projects (slug,title,client_label,year_label,discipline,project_type,challenge,idea,outcome,cover_path,cover_alt,gallery,featured,position,status,hue,locale,updated_at) values
('diga-yes','Diga YES & Viva o Mundo Online','Webmasters / YES','2026','Campaign Design','Campaign Design','A YES precisava de transformar planos de fibra — um produto técnico e invisível — numa promessa emocional que qualquer pessoa em Maputo entendesse num relance.','Um key visual tipográfico em 3D, «Diga YES & Viva o Mundo Online», sobre um universo azul-eléctrico de cortinas de luz e velocidade. Cada post traduz um benefício — estudar, jogar, trabalhar, ver — numa cena doméstica suspensa nesse mesmo mundo.','Um sistema de campanha modular: um master KV e uma família de posts sociais prontos a escalar, mantendo preços, planos e assinatura de marca sempre legíveis.','/__l5e/assets-v1/605e53c9-7a73-4f78-aef0-7960296bb6f9/diga-yes-kv.webp','Diga YES & Viva o Mundo Online','["/__l5e/assets-v1/c06bd5dd-c9f1-49fa-8b8b-05cad77f2931/diga-yes-kv-wide.webp","/__l5e/assets-v1/c882e605-e48c-4544-8acc-7ac31b9625ee/diga-yes-p1.webp","/__l5e/assets-v1/d0d939f5-82c3-4185-a618-4ac43565c8a9/diga-yes-p2.webp","/__l5e/assets-v1/28741bad-38b7-4586-9ce2-e18c2a9644f3/diga-yes-p3.webp","/__l5e/assets-v1/e0bacb0b-aafa-4a30-a706-8edc4b9767da/diga-yes-p4.webp","/__l5e/assets-v1/6e505ddd-d316-4710-bc92-861e0fb7f265/diga-yes-p5.webp"]'::jsonb,TRUE,0,'published',215,'pt-MZ','2026-10-29T07:17:46.633Z'),
('jogue-venca-repita','Jogue, Vença, Repita.','Webmasters','2026','Social Media','Social Media','Falar com gamers e heavy users sem cair no cliché do neon roxo — e provar que a velocidade da Webmasters aguenta o que mais exige da rede.','Retratos cinematográficos em azul profundo, energia de arena de e-sports e planos apresentados como chips de interface de jogo. O produto entra como power-up, não como tabela de preços.','Uma linha social de alta performance que estendeu a linguagem para o 4G — «para quem não para de fazer acontecer» — com o mesmo ritmo visual.','/__l5e/assets-v1/5ac0ccab-4fac-45d8-8cff-bc19c8432208/gaming.webp','Jogue, Vença, Repita.','["/__l5e/assets-v1/99687d02-1ddf-4ad4-8fa2-686bfe0aad09/gaming-2.webp","/__l5e/assets-v1/f8ab00df-c4b4-4f6b-8a69-f62b1e674437/4g.webp"]'::jsonb,TRUE,1,'published',195,'pt-MZ','2026-10-29T07:17:46.633Z'),
('datas-que-ligam','Datas que Ligam','Webmasters / YES','2025 — 2026','Content Creation','Content Creation','Manter a marca presente todo o ano sem repetir fórmulas: Dia dos Namorados, 8 de Março, Outubro Rosa, Natal e Dia Internacional do Obrigado.','Cada data ganha o seu próprio universo — do coração-wireframe dos Namorados ao wifi feito de laços cor-de-rosa — sempre com o azul Webmasters como fio condutor e a assinatura «Diga YES».','Um calendário comemorativo completo, com peças distintas entre si mas inconfundivelmente da mesma marca.','/__l5e/assets-v1/e14ae67a-1781-4936-91db-aaa146b9d180/namorados.webp','Datas que Ligam','["/__l5e/assets-v1/63ea800d-8725-4d35-9c37-5fbbfd65e3e4/namorados-1.webp","/__l5e/assets-v1/4642665e-816b-4fbf-8f43-b0e40ae6b5fe/namorados-2.webp","/__l5e/assets-v1/4e9e1a6a-8e37-443c-9586-db26041e7d51/8marco.webp","/__l5e/assets-v1/1c75390e-c4be-45cc-9711-d77cc8d102d4/outubro-rosa.webp","/__l5e/assets-v1/0f342a1c-1734-4967-940c-3b3fd3c0e444/natal.webp","/__l5e/assets-v1/38be3319-a207-4ebb-8717-a056f00bc557/obrigado.webp","/__l5e/assets-v1/a50d0feb-f8d9-4528-aa13-1487fffd7e21/obrigado-2.webp"]'::jsonb,TRUE,2,'published',330,'pt-MZ','2026-10-29T07:17:46.633Z'),
('somos-uma','Somos Uma','Webmasters','2026','Art Direction','Art Direction','Humanizar um ISP: passar de «vendemos internet» para «somos uma equipa que resolve» — e explicar serviços como Entidade & Referência ou actualizações fora do pico sem adormecer ninguém.','Fotografia de retrato com luz de estúdio azul, ícones desenhados à mão sobre a imagem e titulares directos em peso máximo. Cada peça responde a uma pergunta real do cliente.','Uma série institucional que deu rosto, tom e confiança à marca — do atendimento à velocidade, do pagamento à manutenção.','/__l5e/assets-v1/cf88c1d5-6086-4ab7-a053-0a3dc3babde1/somos-uma.webp','Somos Uma','["/__l5e/assets-v1/29ba23b3-a294-4989-9454-6acc27678f58/velocidade.webp","/__l5e/assets-v1/3978033e-d3f0-44a3-b4d5-890752d899ae/entidade-ref.webp","/__l5e/assets-v1/51209f28-cdcc-40dd-92b6-e2aeff146c9c/actualizacoes.webp"]'::jsonb,TRUE,3,'published',230,'pt-MZ','2026-10-29T07:17:46.633Z')
